def test_once_threadsafe():
    calls = [0]

    @once
    def setup():
        calls[0] += 1
        return 'val'

    results = []
    barrier = threading.Barrier(5)

    def worker():
        barrier.wait()
        results.append(setup())

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert results == ['val'] * 5
    assert calls[0] == 1
