def test_partial_ordering_basic():
    @partial_ordering
    class MySet(set):
        def __le__(self, other):
            return self.issubset(other)

        def __ge__(self, other):
            return self.issuperset(other)

    a = MySet([1, 2, 3])
    b = MySet([1, 2])
    c = MySet([1, 2, 4])
    assert b < a
    assert not (b > a)
    assert b < c
    assert not (a < c)
    assert not (c > a)


def test_partial_ordering_does_not_override():
    def my_lt(self, other):
        return 'custom'

    @partial_ordering
    class Foo:
        __lt__ = my_lt

        def __le__(self, other):
            return True

        def __ge__(self, other):
            return True

    assert Foo.__lt__ is my_lt
    assert Foo.__eq__ is not None


def test_partial_ordering_eq():
    @partial_ordering
    class S(set):
        def __le__(self, other):
            return self.issubset(other)

        def __ge__(self, other):
            return self.issuperset(other)

    assert S([1, 2]) == S([1, 2])
    assert not (S([1, 2]) == S([1, 2, 3]))


