    @once
    def setup():
        calls.append(1)
        return 42

    results = []
    barrier = threading.Barrier(5)

    def worker():
        barrier.wait()
        results.append(setup())

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert results == [42] * 5
    assert len(calls) == 1


