def test_once_thread_safe():
    calls = []

    @once
    def setup():
        time.sleep(0.02)
        calls.append(1)
        return 'value'

    results = []
    threads = []

    def worker():
        results.append(setup())

    for _ in range(5):
        t = threading.Thread(target=worker)
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    assert results == ['value'] * 5
    assert calls == [1]
