def test_once_thread_safety():
    counter = {'n': 0}
    barrier = threading.Barrier(5)

    @once
    def setup():
        counter['n'] += 1
        return 'val'

    results = []

    def worker():
        barrier.wait()
        results.append(setup())

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert results == ['val'] * 5
    assert counter['n'] == 1


