def test_once_thread_safe():
    calls = []
    started = threading.Event()

    @once
    def setup():
        started.set()
        calls.append(1)
        return 'value'

    results = []

    def worker():
        results.append(setup())

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for t in threads:
