def test_once_thread_safety():
    counter = []
    barrier = threading.Barrier(5)

    @once
    def setup():
        counter.append(1)
        return 'result'

    results = []

    def worker():
        barrier.wait()
        results.append(setup())

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert counter == [1]
    assert results == ['result'] * 5
