def test_once_thread_safe():
    calls = []
    barrier = threading.Barrier(5)
    results = []

    @once
    def setup():
        calls.append(1)
        return 'result'

    def worker():
        barrier.wait()
        results.append(setup())

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert len(calls) == 1
    assert results == ['result'] * 5


